98	export const ParserMixin = (Base) => class extends Base {
99	  constructor(...args) {
100	    super(...args);
101	    this.currentEvent = null;
102	    this.yamlVersion = null;
103	    this.tagHandles = new Map();
104	    this.states = [];
105	    this.marks = [];
106	    this.state = this.parseStreamStart;
107	  }
108	
109	  dispose() {
110	    // Reset the state attributes (to clear self-references)
111	    this.states = [];
112	    this.state = null;
113	  }
114	
115	  checkEvent(...choices) {
116	    // Check the type of the next event.
117	    if (this.currentEvent === null) {
118	      if (this.state) this.currentEvent = this.state.call(this);
119	    }
120	    if (this.currentEvent !== null) {
121	      if (choices.length === 0) return true;
122	      for (const choice of choices) {
123	        if (this.currentEvent instanceof choice) return true;
124	      }
125	    }
126	    return false;
127	  }
128	
129	  peekEvent() {
130	    // Get the next event.
131	    if (this.currentEvent === null) {
132	      if (this.state) this.currentEvent = this.state.call(this);
133	    }
134	    return this.currentEvent;
135	  }
136	
137	  getEvent() {
138	    // Get the next event and proceed further.
139	    if (this.currentEvent === null) {
140	      if (this.state) this.currentEvent = this.state.call(this);
141	    }
142	    const value = this.currentEvent;
143	    this.currentEvent = null;
144	    return value;
145	  }
146	
147	  parseStreamStart() {
148	    // Parse the stream start.
149	    const token = this.getToken();
150	    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);
151	
152	    // Prepare the next state.
153	    this.state = this.parseImplicitDocumentStart;
154	
155	    return event;
156	  }
157	
158	  parseImplicitDocumentStart() {
159	    // Parse an implicit document.
160	    if (!this.checkToken(DirectiveToken, DocumentStartToken, StreamEndToken)) {
161	      this.tagHandles = DEFAULT_TAGS;
162	      const token = this.peekToken();
163	      const startMark = token.startMark;
164	      const endMark = startMark;
165	      const event = new DocumentStartEvent(startMark, endMark, false);
166	
167	      // Prepare the next state.
168	      this.states.push(this.parseDocumentEnd);
169	      this.state = this.parseBlockNode;
170	
171	      return event;
172	    }
173	    return this.parseDocumentStart();
174	  }
175	
176	  parseDocumentStart() {
177	    // Parse any extra document end indicators.
178	    while (this.checkToken(DocumentEndToken)) this.getToken();
179	
180	    // Parse an explicit document.
181	    let event;
182	    if (!this.checkToken(StreamEndToken)) {
183	      let token = this.peekToken();
184	      const startMark = token.startMark;
185	      const [version, tags] = this.processDirectives();
186	      if (!this.checkToken(DocumentStartToken)) {
187	        throw new ParserError(null, null,
188	          `expected '<document start>', but found ${repr(this.peekToken().id)}`,
189	          this.peekToken().startMark);
190	      }
191	      token = this.getToken();
192	      const endMark = token.endMark;
193	      event = new DocumentStartEvent(startMark, endMark, true, version, tags);
194	      this.states.push(this.parseDocumentEnd);
195	      this.state = this.parseDocumentContent;
196	    } else {
197	      // Parse the end of the stream.
198	      const token = this.getToken();
199	      event = new StreamEndEvent(token.startMark, token.endMark);
200	      if (this.states.length) throw new Error('AssertionError: not self.states');
201	      if (this.marks.length) throw new Error('AssertionError: not self.marks');
202	      this.state = null;
203	    }
204	    return event;
205	  }
206	
207	  parseDocumentEnd() {
208	    // Parse the document end.
209	    let token = this.peekToken();
210	    const startMark = token.startMark;
211	    let endMark = startMark;
212	    let explicit = false;
213	    if (this.checkToken(DocumentEndToken)) {
214	      token = this.getToken();
215	      endMark = token.endMark;
216	      explicit = true;
217	    }
218	    const event = new DocumentEndEvent(startMark, endMark, explicit);
219	
220	    // Prepare the next state.
221	    this.state = this.parseDocumentStart;
222	
223	    return event;
224	  }
225	
226	  parseDocumentContent() {
227	    if (this.checkToken(DirectiveToken, DocumentStartToken, DocumentEndToken,
228	      StreamEndToken)) {
229	      const event = this.processEmptyScalar(this.peekToken().startMark);
230	      this.state = this.states.pop();
231	      return event;
232	    }
233	    return this.parseBlockNode();
234	  }
235	
236	  processDirectives() {
237	    this.yamlVersion = null;
238	    this.tagHandles = new Map();
239	    while (this.checkToken(DirectiveToken)) {
240	      const token = this.getToken();
241	      if (token.name === 'YAML') {
242	        if (this.yamlVersion !== null) {
243	          throw new ParserError(null, null,
244	            'found duplicate YAML directive', token.startMark);
245	        }
246	        const [major] = token.value;
247	        if (Number(major) !== 1) {
248	          throw new ParserError(null, null,
249	            'found incompatible YAML document (version 1.* is required)',
250	            token.startMark);
251	        }
252	        this.yamlVersion = token.value;
253	      } else if (token.name === 'TAG') {
254	        const [handle, prefix] = token.value;
255	        if (this.tagHandles.has(handle)) {
256	          throw new ParserError(null, null,
257	            `duplicate tag handle ${repr(handle)}`, token.startMark);
258	        }
259	        this.tagHandles.set(handle, prefix);
260	      }
261	    }
262	    let value;
263	    if (this.tagHandles.size) value = [this.yamlVersion, new Map(this.tagHandles)];
264	    else value = [this.yamlVersion, null];
265	    for (const key of DEFAULT_TAGS.keys()) {
266	      if (!this.tagHandles.has(key)) this.tagHandles.set(key, DEFAULT_TAGS.get(key));
267	    }
268	    return value;
269	  }
270	
271	  parseBlockNode() {
272	    return this.parseNode(true);
273	  }
274	
275	  parseFlowNode() {
276	    return this.parseNode();
277	  }
278	
279	  parseBlockNodeOrIndentlessSequence() {
280	    return this.parseNode(true, true);
281	  }
282	
283	  parseNode(block = false, indentlessSequence = false) {
284	    let event;
285	    if (this.checkToken(AliasToken)) {
286	      const token = this.getToken();
287	      event = new AliasEvent(token.value, token.startMark, token.endMark);
288	      this.state = this.states.pop();
289	    } else {
290	      let anchor = null;
291	      let tag = null;
292	      let startMark = null;
293	      let endMark = null;
294	      let tagMark = null;
295	      if (this.checkToken(AnchorToken)) {
296	        let token = this.getToken();
297	        startMark = token.startMark;
298	        endMark = token.endMark;
299	        anchor = token.value;
300	        if (this.checkToken(TagToken)) {
301	          token = this.getToken();
302	          tagMark = token.startMark;
303	          endMark = token.endMark;
304	          tag = token.value;
305	        }
306	      } else if (this.checkToken(TagToken)) {
307	        let token = this.getToken();
308	        startMark = token.startMark;
309	        tagMark = token.startMark;
310	        endMark = token.endMark;
311	        tag = token.value;
312	        if (this.checkToken(AnchorToken)) {
313	          token = this.getToken();
314	          endMark = token.endMark;
315	          anchor = token.value;
316	        }
317	      }
318	      if (tag !== null) {
319	        const [handle, suffix] = tag;
320	        if (handle !== null) {
321	          if (!this.tagHandles.has(handle)) {
322	            throw new ParserError('while parsing a node', startMark,
323	              `found undefined tag handle ${repr(handle)}`, tagMark);
324	          }
325	          tag = this.tagHandles.get(handle) + suffix;
326	        } else {
327	          tag = suffix;
328	        }
329	      }
330	      // PyYAML keeps the non-specific-tag check commented out here.
331	      if (startMark === null) {
332	        startMark = this.peekToken().startMark;
333	        endMark = startMark;
334	      }
335	      event = null;
336	      let implicit = (tag === null || tag === '!');
337	      if (indentlessSequence && this.checkToken(BlockEntryToken)) {
338	        endMark = this.peekToken().endMark;
339	        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark);
340	        this.state = this.parseIndentlessSequenceEntry;
341	      } else if (this.checkToken(ScalarToken)) {
342	        const token = this.getToken();
343	        endMark = token.endMark;
344	        let scalarImplicit;
345	        if ((token.plain && tag === null) || tag === '!') scalarImplicit = [true, false];
346	        else if (tag === null) scalarImplicit = [false, true];
347	        else scalarImplicit = [false, false];
348	        event = new ScalarEvent(anchor, tag, scalarImplicit, token.value,
349	          startMark, endMark, token.style);
350	        this.state = this.states.pop();
351	      } else if (this.checkToken(FlowSequenceStartToken)) {
352	        endMark = this.peekToken().endMark;
353	        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
354	        this.state = this.parseFlowSequenceFirstEntry;
355	      } else if (this.checkToken(FlowMappingStartToken)) {
356	        endMark = this.peekToken().endMark;
357	        event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
358	        this.state = this.parseFlowMappingFirstKey;
359	      } else if (block && this.checkToken(BlockSequenceStartToken)) {
360	        endMark = this.peekToken().startMark;
361	        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
362	        this.state = this.parseBlockSequenceFirstEntry;
363	      } else if (block && this.checkToken(BlockMappingStartToken)) {
364	        endMark = this.peekToken().startMark;
365	        event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
366	        this.state = this.parseBlockMappingFirstKey;
367	      } else if (anchor !== null || tag !== null) {
368	        // Empty scalars are allowed even if a tag or an anchor is specified.
369	        event = new ScalarEvent(anchor, tag, [implicit, false], '', startMark, endMark);
370	        this.state = this.states.pop();
371	      } else {
372	        const node = block ? 'block' : 'flow';
373	        const token = this.peekToken();
374	        throw new ParserError(`while parsing a ${node} node`, startMark,
375	          `expected the node content, but found ${repr(token.id)}`, token.startMark);
376	      }
377	    }
378	    return event;
379	  }
380	
381	  parseBlockSequenceFirstEntry() {
382	    const token = this.getToken();
383	    this.marks.push(token.startMark);
384	    return this.parseBlockSequenceEntry();
385	  }
386	
387	  parseBlockSequenceEntry() {
388	    if (this.checkToken(BlockEntryToken)) {
389	      const token = this.getToken();
390	      if (!this.checkToken(BlockEntryToken, BlockEndToken)) {
391	        this.states.push(this.parseBlockSequenceEntry);
392	        return this.parseBlockNode();
393	      }
394	      this.state = this.parseBlockSequenceEntry;
395	      return this.processEmptyScalar(token.endMark);
396	    }
397	    if (!this.checkToken(BlockEndToken)) {
398	      const token = this.peekToken();
399	      throw new ParserError('while parsing a block collection', this.marks[this.marks.length - 1],
400	        `expected <block end>, but found ${repr(token.id)}`, token.startMark);
401	    }
402	    const token = this.getToken();
403	    const event = new SequenceEndEvent(token.startMark, token.endMark);
404	    this.state = this.states.pop();
405	    this.marks.pop();
406	    return event;
407	  }
408	
409	  parseIndentlessSequenceEntry() {
410	    if (this.checkToken(BlockEntryToken)) {
411	      const token = this.getToken();
412	      if (!this.checkToken(BlockEntryToken, KeyToken, ValueToken, BlockEndToken)) {
413	        this.states.push(this.parseIndentlessSequenceEntry);
414	        return this.parseBlockNode();
415	      }
416	      this.state = this.parseIndentlessSequenceEntry;
417	      return this.processEmptyScalar(token.endMark);
418	    }
419	    const token = this.peekToken();
420	    const event = new SequenceEndEvent(token.startMark, token.startMark);
421	    this.state = this.states.pop();
422	    return event;
423	  }
424	
425	  parseBlockMappingFirstKey() {
426	    const token = this.getToken();
427	    this.marks.push(token.startMark);
428	    return this.parseBlockMappingKey();
429	  }
430	
431	  parseBlockMappingKey() {
432	    if (this.checkToken(KeyToken)) {
433	      const token = this.getToken();
434	      if (!this.checkToken(KeyToken, ValueToken, BlockEndToken)) {
435	        this.states.push(this.parseBlockMappingValue);
436	        return this.parseBlockNodeOrIndentlessSequence();
437	      }
438	      this.state = this.parseBlockMappingValue;
439	      return this.processEmptyScalar(token.endMark);
440	    }
441	    if (!this.checkToken(BlockEndToken)) {
442	      const token = this.peekToken();
443	      throw new ParserError('while parsing a block mapping', this.marks[this.marks.length - 1],
444	        `expected <block end>, but found ${repr(token.id)}`, token.startMark);
445	    }
446	    const token = this.getToken();
447	    const event = new MappingEndEvent(token.startMark, token.endMark);
448	    this.state = this.states.pop();
449	    this.marks.pop();
450	    return event;
451	  }
452	
453	  parseBlockMappingValue() {
454	    if (this.checkToken(ValueToken)) {
455	      const token = this.getToken();
456	      if (!this.checkToken(KeyToken, ValueToken, BlockEndToken)) {
457	        this.states.push(this.parseBlockMappingKey);
458	        return this.parseBlockNodeOrIndentlessSequence();
459	      }
460	      this.state = this.parseBlockMappingKey;
461	      return this.processEmptyScalar(token.endMark);
462	    }
463	    this.state = this.parseBlockMappingKey;
464	    const token = this.peekToken();
465	    return this.processEmptyScalar(token.startMark);
466	  }
467	
468	  // Note that while production rules for both flow_sequence_entry and
469	  // flow_mapping_entry are equal, their interpretations are different.
470	  // For `flow_sequence_entry`, the part `KEY flow_node? (VALUE flow_node?)?`
471	  // generate an inline mapping (set syntax).
472	
473	  parseFlowSequenceFirstEntry() {
474	    const token = this.getToken();
475	    this.marks.push(token.startMark);
476	    return this.parseFlowSequenceEntry(true);
477	  }
478	
479	  parseFlowSequenceEntry(first = false) {
480	    if (!this.checkToken(FlowSequenceEndToken)) {
481	      if (!first) {
482	        if (this.checkToken(FlowEntryToken)) {
483	          this.getToken();
484	        } else {
485	          const token = this.peekToken();
486	          throw new ParserError('while parsing a flow sequence', this.marks[this.marks.length - 1],
487	            `expected ',' or ']', but got ${repr(token.id)}`, token.startMark);
488	        }
489	      }
490	      if (this.checkToken(KeyToken)) {
491	        const token = this.peekToken();
492	        const event = new MappingStartEvent(null, null, true,
493	          token.startMark, token.endMark, true);
494	        this.state = this.parseFlowSequenceEntryMappingKey;
495	        return event;
496	      }
497	      if (!this.checkToken(FlowSequenceEndToken)) {
498	        this.states.push(this.parseFlowSequenceEntry);
499	        return this.parseFlowNode();
500	      }
501	    }
502	    const token = this.getToken();
503	    const event = new SequenceEndEvent(token.startMark, token.endMark);
504	    this.state = this.states.pop();
505	    this.marks.pop();
506	    return event;
507	  }
508	
509	  parseFlowSequenceEntryMappingKey() {
510	    const token = this.getToken();
511	    if (!this.checkToken(ValueToken, FlowEntryToken, FlowSequenceEndToken)) {
512	      this.states.push(this.parseFlowSequenceEntryMappingValue);
513	      return this.parseFlowNode();
514	    }
515	    this.state = this.parseFlowSequenceEntryMappingValue;
516	    return this.processEmptyScalar(token.endMark);
517	  }
518	
519	  parseFlowSequenceEntryMappingValue() {
520	    if (this.checkToken(ValueToken)) {
521	      const token = this.getToken();
522	      if (!this.checkToken(FlowEntryToken, FlowSequenceEndToken)) {
523	        this.states.push(this.parseFlowSequenceEntryMappingEnd);
524	        return this.parseFlowNode();
525	      }
526	      this.state = this.parseFlowSequenceEntryMappingEnd;
527	      return this.processEmptyScalar(token.endMark);
528	    }
529	    this.state = this.parseFlowSequenceEntryMappingEnd;
530	    const token = this.peekToken();
531	    return this.processEmptyScalar(token.startMark);
532	  }
533	
534	  parseFlowSequenceEntryMappingEnd() {
535	    this.state = this.parseFlowSequenceEntry;
536	    const token = this.peekToken();
537	    return new MappingEndEvent(token.startMark, token.startMark);
538	  }
539	
540	  parseFlowMappingFirstKey() {
541	    const token = this.getToken();
542	    this.marks.push(token.startMark);
543	    return this.parseFlowMappingKey(true);
544	  }
545	
546	  parseFlowMappingKey(first = false) {
547	    if (!this.checkToken(FlowMappingEndToken)) {
548	      if (!first) {
549	        if (this.checkToken(FlowEntryToken)) {
550	          this.getToken();
551	        } else {
552	          const token = this.peekToken();
553	          throw new ParserError('while parsing a flow mapping', this.marks[this.marks.length - 1],
554	            `expected ',' or '}', but got ${repr(token.id)}`, token.startMark);
555	        }
556	      }
557	      if (this.checkToken(KeyToken)) {
558	        const token = this.getToken();
559	        if (!this.checkToken(ValueToken, FlowEntryToken, FlowMappingEndToken)) {
560	          this.states.push(this.parseFlowMappingValue);
561	          return this.parseFlowNode();
562	        }
563	        this.state = this.parseFlowMappingValue;
564	        return this.processEmptyScalar(token.endMark);
565	      }
566	      if (!this.checkToken(FlowMappingEndToken)) {
567	        this.states.push(this.parseFlowMappingEmptyValue);
568	        return this.parseFlowNode();
569	      }
570	    }
571	    const token = this.getToken();
572	    const event = new MappingEndEvent(token.startMark, token.endMark);
573	    this.state = this.states.pop();
574	    this.marks.pop();
575	    return event;
576	  }
577	
578	  parseFlowMappingValue() {
579	    if (this.checkToken(ValueToken)) {
580	      const token = this.getToken();
581	      if (!this.checkToken(FlowEntryToken, FlowMappingEndToken)) {
582	        this.states.push(this.parseFlowMappingKey);
583	        return this.parseFlowNode();
584	      }
585	      this.state = this.parseFlowMappingKey;
586	      return this.processEmptyScalar(token.endMark);
587	    }
588	    this.state = this.parseFlowMappingKey;
589	    const token = this.peekToken();
590	    return this.processEmptyScalar(token.startMark);
