// Differential test harness: run the reference executable and our port over the
// same --a value and compare stdout bytes + exit code exactly.
//
// Not part of the deliverable — lives outside /output and may use node: builtins.

import { spawnSync } from 'node:child_process';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

const REF = '/workspace/dataset/test4_executable';
const OURS = ['node', '/output/test4.mjs'];

function runRef(value) {
  const r = spawnSync(REF, ['--a', value], { encoding: 'buffer', maxBuffer: 1 << 26 });
  return { out: r.stdout ?? Buffer.alloc(0), err: r.stderr ?? Buffer.alloc(0), code: r.status };
}

function runOurs(value) {
  const r = spawnSync(OURS[0], [OURS[1], '--a', value], { encoding: 'buffer', maxBuffer: 1 << 26 });
  return { out: r.stdout ?? Buffer.alloc(0), err: r.stderr ?? Buffer.alloc(0), code: r.status };
}

/** The trailing `module.ErrorClass: message` block Python prints, if any. */
function errorTail(buf) {
  const text = buf.toString('utf8');
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const colon = line.indexOf(': ');
    const head = colon < 0 ? line : line.slice(0, colon);
    if (head.startsWith('yaml.') || head === 'ValueError' || head === 'TypeError' ||
      head === 'binascii.Error' || head === 'OverflowError') {
      return lines.slice(i).filter((l) => !l.startsWith('[PYI-')).join('\n').trimEnd();
    }
  }
  return null;
}

function show(buf) {
  let out = '';
  for (const b of buf) {
    if (b === 0x0a) out += '\\n';
    else if (b === 0x09) out += '\\t';
    else if (b < 0x20 || b === 0x7f) out += '\\x' + b.toString(16).padStart(2, '0');
    else out += String.fromCharCode(b);
  }
  return out;
}

function collectCases(dir) {
  const cases = [];
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) cases.push(...collectCases(p));
    else cases.push({ name: p, value: readFileSync(p, 'utf8') });
  }
  return cases;
}

const dir = process.argv[2] ?? '/workspace/cases';
const verbose = process.argv.includes('--verbose');
const cases = collectCases(dir);

let pass = 0;
const failures = [];

for (const c of cases) {
  const a = runRef(c.value);
  const b = runOurs(c.value);
  const outMatch = a.out.equals(b.out);
  const codeMatch = a.code === b.code;
  const refTail = errorTail(a.err);
  const ourTail = errorTail(b.err);
  const errMatch = refTail === null ? true : refTail === ourTail;

  if (outMatch && codeMatch && errMatch) {
    pass++;
    if (verbose) console.log(`ok   ${c.name}`);
    continue;
  }
  failures.push({ c, a, b, outMatch, codeMatch, errMatch, refTail, ourTail });
}

for (const f of failures) {
  console.log(`\nFAIL ${f.c.name}`);
  console.log(`  input   : ${show(Buffer.from(f.c.value, 'utf8'))}`);
  if (!f.codeMatch) console.log(`  exit    : ref=${f.a.code} ours=${f.b.code}`);
  if (!f.outMatch) {
    console.log(`  ref out : ${show(f.a.out)}`);
    console.log(`  our out : ${show(f.b.out)}`);
  }
  if (!f.errMatch) {
    console.log(`  ref err : ${f.refTail}`);
    console.log(`  our err : ${f.ourTail === null ? '(none)' : f.ourTail}`);
    if (f.ourTail === null) {
      console.log(`  our raw : ${f.b.err.toString('utf8').trimEnd().split('\n').slice(-6).join(' | ')}`);
    }
  }
}

console.log(`\n${pass}/${cases.length} passed, ${failures.length} failed`);
process.exit(failures.length === 0 ? 0 : 1);
